import { useEffect, useMemo, useState } from "react";
import { getVendorProducts, saveProduct, deleteVendorProduct } from "../../api/productApi";
import { getCategories } from "../../api/categoryApi";
import { Save, Pencil, Trash2, X } from "lucide-react";
const blank={name:"",sku:"",categoryId:"",subcategoryId:"",brand:"",description:"",unit:"piece",price:0,mrp:0,taxRate:5,stock:0,lowStockThreshold:5,images:[],variants:[],featured:false};
const unwrap=r=>Array.isArray(r?.data?.data)?r.data.data:Array.isArray(r?.data)?r.data:[];
export default function ProductManager(){
 const [products,setProducts]=useState([]),[categories,setCategories]=useState([]),[form,setForm]=useState(blank),[editingId,setEditingId]=useState(null),[message,setMessage]=useState(""),[error,setError]=useState(""),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[categoriesLoading,setCategoriesLoading]=useState(true);
 const loadProducts=async()=>{setProducts(unwrap(await getVendorProducts()));};
 const loadCategories=async()=>{setCategoriesLoading(true);try{setCategories(unwrap(await getCategories()).filter(c=>c.active!==false));setError("");}catch(e){setError(e.response?.data?.message||"Could not load categories. Please retry.");}finally{setCategoriesLoading(false);}};
 useEffect(()=>{Promise.all([loadProducts(),loadCategories()]).catch(e=>setError(e.response?.data?.message||"Could not load products.")).finally(()=>setLoading(false));},[]);
 const subcategories=useMemo(()=>categories.filter(c=>String(c.parentId||"")===String(form.categoryId||"")&&!!form.categoryId),[categories,form.categoryId]);
 const reset=()=>{setForm(blank);setEditingId(null);}; const update=(k,v)=>setForm(f=>({...f,[k]:v}));
 const save=async()=>{setMessage("");setError("");if(!form.name.trim())return setError("Please enter a product name.");if(!form.sku.trim())return setError("Please enter an SKU.");if(!form.categoryId)return setError("Please select a category.");setSaving(true);try{await saveProduct({...form,price:Number(form.price),mrp:Number(form.mrp),taxRate:Number(form.taxRate),stock:Number(form.stock),lowStockThreshold:Number(form.lowStockThreshold)},editingId);setMessage(editingId?"Product updated.":"Product submitted for admin approval.");reset();await loadProducts();}catch(e){setError(e.response?.data?.message||"Could not save product.");}finally{setSaving(false);}};
 const edit=x=>{setEditingId(x.id);setForm({...blank,...x,images:x.images||[],variants:x.variants||[],subcategoryId:x.subcategoryId||""});setMessage("");setError("");window.scrollTo({top:0,behavior:"smooth"});};
 const remove=async x=>{if(!window.confirm(`Delete product "${x.name}"? This cannot be undone.`))return;try{await deleteVendorProduct(x.id);setMessage("Product deleted.");if(editingId===x.id)reset();await loadProducts();}catch(e){setError(e.response?.data?.message||"Could not delete product.");}};
 return <div className="page-shell vendor-bg"><p className="eyebrow">PRODUCT OPERATIONS</p><h1 className="page-title">Products &amp; inventory</h1>{message&&<div className="mt-4 rounded-xl bg-slate-900 p-3 text-sm font-semibold text-white">{message}</div>}{error&&<div className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error} <button className="ml-2 underline" onClick={loadCategories}>Retry categories</button></div>}
 <div className="mt-6 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><section className="card p-5"><div className="flex items-center justify-between gap-2"><h2 className="font-black">{editingId?"Edit product":"Add product"}</h2>{editingId&&<button className="btn-secondary" onClick={reset}><X size={16}/> Cancel</button>}</div><div className="mt-4 grid gap-3">
 <label><span className="label">Product name</span><input className="input" value={form.name} onChange={e=>update("name",e.target.value)}/></label><label><span className="label">SKU</span><input className="input" value={form.sku} onChange={e=>update("sku",e.target.value)}/></label>
 <label><span className="label">Category</span><select className="input" value={form.categoryId} disabled={categoriesLoading} onChange={e=>setForm(f=>({...f,categoryId:e.target.value,subcategoryId:""}))}><option value="">{categoriesLoading?"Loading categories…":"Select category"}</option>{categories.filter(c=>!c.parentId).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
 <label><span className="label">Subcategory</span><select className="input" value={form.subcategoryId||""} disabled={!form.categoryId||categoriesLoading||!subcategories.length} onChange={e=>update("subcategoryId",e.target.value)}><option value="">{!form.categoryId?"Select a category first":subcategories.length?"Select subcategory":"No subcategories available"}</option>{subcategories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
 <label><span className="label">Brand</span><input className="input" value={form.brand} onChange={e=>update("brand",e.target.value)}/></label><label><span className="label">Unit</span><input className="input" value={form.unit} onChange={e=>update("unit",e.target.value)}/></label>
 <div className="grid grid-cols-2 gap-3">{[["price","Selling price"],["mrp","MRP"],["taxRate","Tax %"],["stock","Opening stock"],["lowStockThreshold","Low stock alert"]].map(([k,l])=><label key={k}><span className="label">{l}</span><input type="number" min="0" className="input" value={form[k]} onChange={e=>update(k,e.target.value)}/></label>)}</div>
 <label><span className="label">Image URL</span><input className="input" value={form.images?.[0]||""} onChange={e=>update("images",e.target.value?[e.target.value]:[])}/></label><label><span className="label">Description</span><textarea className="input min-h-28" value={form.description} onChange={e=>update("description",e.target.value)}/></label><button className="btn-primary" disabled={saving||categoriesLoading} onClick={save}><Save size={16}/>{saving?"Saving…":editingId?"Save changes":"Submit product"}</button></div></section>
 <section className="card p-5"><h2 className="font-black">My products</h2>{loading?<p className="mt-4 text-sm text-slate-500">Loading products…</p>:<div className="mt-4 space-y-3">{products.map(x=><div key={x.id} className="rounded-xl border border-slate-100 p-4"><div className="flex flex-wrap justify-between gap-3"><div><b>{x.name}</b><p className="text-xs text-slate-500">SKU {x.sku} · ₹{x.price} · tax {x.taxRate}%</p><p className="text-xs text-slate-500">{categories.find(c=>c.id===x.categoryId)?.name||"Category"}{x.subcategoryId?` · ${categories.find(c=>c.id===x.subcategoryId)?.name||"Subcategory"}`:""}</p></div><span className="status-pill bg-slate-100">{x.approved?"APPROVED":"PENDING APPROVAL"}</span></div><p className="mt-2 text-xs text-slate-500">Variants: {x.variants?.length||0}</p><div className="mt-3 flex gap-2"><button className="btn-secondary" onClick={()=>edit(x)}><Pencil size={14}/> Edit</button><button className="btn-secondary text-red-600" onClick={()=>remove(x)}><Trash2 size={14}/> Delete</button></div></div>)}{!products.length&&<p className="text-sm text-slate-400">No products yet.</p>}</div>}</section></div></div>;
}
